VOWELS = "aeiou"


def _translate_word(word):
    # Rule 1: starts with a vowel, or with "xr" or "yt"
    if word[0] in VOWELS or word.startswith(("xr", "yt")):
        return word + "ay"

    # Find the end of the leading consonant cluster.
    # "qu" counts as a consonant unit (Rule 3), and "y" counts as a vowel
    # once it is no longer the first letter (Rule 4).
    i = 0
    while i < len(word):
        if word[i] in VOWELS:
            break
        if word[i] == "y" and i > 0:
            break
        if word[i] == "q" and word[i + 1 : i + 2] == "u":
            i += 2
            continue
        i += 1

    # Rules 2 and 3: move the consonant cluster to the end, add "ay"
    return word[i:] + word[:i] + "ay"


def translate(text):
    return " ".join(_translate_word(word) for word in text.split(" "))

